#!/bin/bash
set -euo pipefail
umask 077
DIR="$HOME/.maclock-guardian"
CONFIG="$DIR/config"
[ -r "$CONFIG" ] || { echo 'Configuration missing' >&2; exit 1; }
# Configuration is generated by setup, never committed.
# shellcheck disable=SC1090
source "$CONFIG"
[ -n "${TELEGRAM_BOT_TOKEN:-}" ] && [ -n "${TELEGRAM_CHAT_ID:-}" ] || exit 1
TEXT="MacLock Guardian: incorrect password detected on $(hostname -s)"
if ! /usr/bin/curl --fail --silent --show-error --max-time 20 \
  "https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage" \
  --data-urlencode "chat_id=$TELEGRAM_CHAT_ID" --data-urlencode "text=$TEXT" >/dev/null; then
  echo "$(date): Telegram text delivery failed" >&2
fi
APP="$DIR/MacLockCamera.app"
PHOTO="$DIR/photos/attempt-$(date +%s)-$$.jpg"
# Camera may be unavailable when screen is locked, depending on the OS and permissions.
if [ -x "$APP/Contents/MacOS/MacLockCamera" ]; then
  /usr/bin/open -W "$APP" --args "$PHOTO" >/dev/null 2>&1 &
  pid=$!
  # Wait for the photo to be written, no more than 15 seconds.
  for ((i=0;i<15;i++)); do
    [ -s "$PHOTO" ] && break
    sleep 1
  done
  # Do not kill camera app by process name: only this helper's open job.
  if kill -0 "$pid" 2>/dev/null; then kill "$pid" 2>/dev/null || true; fi
  wait "$pid" 2>/dev/null || true
  if [ -s "$PHOTO" ]; then
    chmod 600 "$PHOTO"
    /usr/bin/curl --fail --silent --show-error --max-time 20 \
      "https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendPhoto" \
      -F "chat_id=$TELEGRAM_CHAT_ID" \
      -F 'caption=MacLock Guardian: failed unlock photo' \
      -F "photo=@$PHOTO" >/dev/null
  else
    echo "$(date): camera failed or no usable frame" >&2
  fi
fi
